#!/usr/bin/env python3
"""Parse application log files.

Expected line format:

    2026-08-01 12:00:00 INFO started
    <date> <time> <LEVEL> <message>
"""

import argparse
import json
import re
import sys
from dataclasses import dataclass, asdict
from datetime import datetime

LINE_RE = re.compile(
    r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+"
    r"(?P<level>[A-Z]+)\s+"
    r"(?P<message>.*)$"
)

TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"


@dataclass
class LogEntry:
    timestamp: datetime
    level: str
    message: str
    source: str
    lineno: int

    def as_dict(self):
        d = asdict(self)
        d["timestamp"] = self.timestamp.isoformat(sep=" ")
        return d


def parse_line(line, source, lineno):
    """Return a LogEntry, or None if the line doesn't match the format."""
    match = LINE_RE.match(line.rstrip("\n"))
    if not match:
        return None
    return LogEntry(
        timestamp=datetime.strptime(match["timestamp"], TIMESTAMP_FORMAT),
        level=match["level"],
        message=match["message"].strip(),
        source=source,
        lineno=lineno,
    )


def parse_file(path):
    """Yield (LogEntry | None, raw_line) for every line in a log file."""
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        for lineno, line in enumerate(fh, start=1):
            if not line.strip():
                continue
            yield parse_line(line, path, lineno), line.rstrip("\n")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("files", nargs="+", help="log files to parse")
    parser.add_argument("--level", action="append", metavar="LEVEL",
                        help="only show these levels (repeatable, e.g. --level WARN --level ERROR)")
    parser.add_argument("--contains", metavar="TEXT",
                        help="only show entries whose message contains TEXT (case-insensitive)")
    parser.add_argument("--json", action="store_true",
                        help="emit entries as JSON instead of text")
    parser.add_argument("--summary", action="store_true",
                        help="print a per-level count instead of the entries")
    args = parser.parse_args(argv)

    wanted = {lvl.upper() for lvl in args.level} if args.level else None
    needle = args.contains.lower() if args.contains else None

    entries = []
    malformed = 0
    for path in args.files:
        try:
            lines = list(parse_file(path))
        except OSError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1
        for entry, raw in lines:
            if entry is None:
                malformed += 1
                print(f"warning: {path}: unparseable line: {raw!r}", file=sys.stderr)
                continue
            if wanted and entry.level not in wanted:
                continue
            if needle and needle not in entry.message.lower():
                continue
            entries.append(entry)

    entries.sort(key=lambda e: e.timestamp)

    if args.summary:
        counts = {}
        for entry in entries:
            counts[entry.level] = counts.get(entry.level, 0) + 1
        if args.json:
            print(json.dumps({"counts": counts, "total": len(entries),
                              "malformed": malformed}, indent=2))
        else:
            for level, count in sorted(counts.items(), key=lambda kv: -kv[1]):
                print(f"{level:<8} {count}")
            print(f"{'TOTAL':<8} {len(entries)}")
            if malformed:
                print(f"{'BAD':<8} {malformed}")
    elif args.json:
        print(json.dumps([e.as_dict() for e in entries], indent=2))
    else:
        for e in entries:
            print(f"{e.timestamp:%Y-%m-%d %H:%M:%S} {e.level:<5} {e.message}")

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Parse application log files of the form:

    2026-08-01 12:00:00 INFO started
    2026-08-01 12:00:01 WARN slow query 431ms
"""

import argparse
import json
import re
import sys
from collections import Counter
from dataclasses import dataclass, asdict
from datetime import datetime
from typing import Iterable, Iterator, Optional

LINE_RE = re.compile(
    r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+"
    r"(?P<level>[A-Z]+)\s+"
    r"(?P<message>.*)$"
)

TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"


@dataclass
class Entry:
    timestamp: datetime
    level: str
    message: str
    source: str
    lineno: int

    def to_dict(self) -> dict:
        d = asdict(self)
        d["timestamp"] = self.timestamp.isoformat()
        return d


class ParseError(Exception):
    """Raised for a line that does not match the log format."""

    def __init__(self, source: str, lineno: int, line: str):
        super().__init__(f"{source}:{lineno}: unparseable line: {line!r}")
        self.source = source
        self.lineno = lineno
        self.line = line


def parse_line(line: str, source: str = "<string>", lineno: int = 0) -> Entry:
    """Parse a single log line into an Entry, or raise ParseError."""
    match = LINE_RE.match(line.rstrip("\n"))
    if not match:
        raise ParseError(source, lineno, line.rstrip("\n"))
    return Entry(
        timestamp=datetime.strptime(match["timestamp"], TIMESTAMP_FORMAT),
        level=match["level"],
        message=match["message"].strip(),
        source=source,
        lineno=lineno,
    )


def parse_lines(
    lines: Iterable[str], source: str = "<stream>", strict: bool = False
) -> Iterator[Entry]:
    """Parse an iterable of lines, skipping blanks.

    Unparseable lines are skipped with a warning, or raise if strict.
    """
    for lineno, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            yield parse_line(line, source, lineno)
        except ParseError as exc:
            if strict:
                raise
            print(f"warning: {exc}", file=sys.stderr)


def parse_file(path: str, strict: bool = False) -> Iterator[Entry]:
    """Parse a log file (use "-" for stdin)."""
    if path == "-":
        yield from parse_lines(sys.stdin, "<stdin>", strict)
        return
    with open(path, encoding="utf-8", errors="replace") as handle:
        yield from parse_lines(handle, path, strict)


def summarize(entries: Iterable[Entry]) -> dict:
    levels: Counter = Counter()
    sources: Counter = Counter()
    first = last = None
    for entry in entries:
        levels[entry.level] += 1
        sources[entry.source] += 1
        if first is None or entry.timestamp < first:
            first = entry.timestamp
        if last is None or entry.timestamp > last:
            last = entry.timestamp
    return {
        "total": sum(levels.values()),
        "levels": dict(levels.most_common()),
        "files": dict(sources.most_common()),
        "first": first.isoformat() if first else None,
        "last": last.isoformat() if last else None,
    }


def main(argv: Optional[list] = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("paths", nargs="*", default=["-"], help='log files ("-" for stdin)')
    parser.add_argument("--level", action="append", help="only show these levels (repeatable)")
    parser.add_argument("--contains", help="only show messages containing this substring")
    parser.add_argument(
        "--format",
        choices=("text", "json", "summary"),
        default="text",
        help="output format (default: text)",
    )
    parser.add_argument("--strict", action="store_true", help="fail on unparseable lines")
    args = parser.parse_args(argv)

    entries = []
    wanted = {level.upper() for level in args.level} if args.level else None
    for path in args.paths or ["-"]:
        try:
            for entry in parse_file(path, args.strict):
                if wanted and entry.level not in wanted:
                    continue
                if args.contains and args.contains not in entry.message:
                    continue
                entries.append(entry)
        except ParseError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1
        except OSError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1

    if args.format == "json":
        json.dump([e.to_dict() for e in entries], sys.stdout, indent=2)
        sys.stdout.write("\n")
    elif args.format == "summary":
        json.dump(summarize(entries), sys.stdout, indent=2)
        sys.stdout.write("\n")
    else:
        for entry in entries:
            print(
                f"{entry.timestamp:%Y-%m-%d %H:%M:%S} "
                f"{entry.level:<5} {entry.message}  ({entry.source}:{entry.lineno})"
            )
    return 0


if __name__ == "__main__":
    sys.exit(main())
